export default async (): Promise<RequestMessage> => (
{
  collection: "example",
  // gv.request.params holds whatever the caller passed for THIS run: the CLI's
  // --param, the MCP tool's `params`, or the second argument of gv.invoke().
  // It is empty on a plain run, so every param needs a default.
  //
  // RunScript with no `kind` evaluates `source` as a scratchpad and returns its
  // last-expression value, so the response echoes the arithmetic back.
  source: String(gv.request.params.expression ?? "1 + 1"),
}
)
